from booking import cancellation_fee


def test_fee_is_zero_at_and_above_24_hours():
    for hours in (24, 48):
        result = cancellation_fee(hours)
        assert isinstance(result, int) and not isinstance(result, bool)
        assert result == 0

from booking import cancellation_fee


def test_fee_is_2500_from_zero_through_23_hours():
    for hours in (0, 23):
        result = cancellation_fee(hours)
        assert isinstance(result, int) and not isinstance(result, bool)
        assert result == 2500

